// Layer 2: Dense (32 -> 2)
static const float L2_WEIGHTS[64] = {-0.03205201f, -0.00942227f, 0.02282273f, 0.00943443f, -0.02051889f, 0.00627907f, 0.01293743f, 0.00024633f, 0.08991250f, 0.09053915f, -0.00130112f, -0.02695042f, 0.06030780f, 0.08041739f, -0.07185423f, -0.04461303f, -0.05457450f, -0.03903233f, 0.06197415f, 0.07681529f, 0.03188260f, 0.05859134f, -0.03333187f, -0.03726641f, 0.00567256f, 0.07052828f, -0.01477182f, 0.01067254f, -0.03395812f, -0.01414298f, -0.10980322f, -0.11911064f, 0.03091119f, 0.03045311f, -0.05254916f, -0.03071423f, -0.07157547f, -0.08251351f, 0.10894238f, 0.06873888f, -0.08849730f, -0.06916973f, 0.02360067f, 0.01835178f, -0.00071407f, -0.01024873f, -0.00007372f, 0.03225323f, -0.01344891f, -0.03641114f, -0.05699258f, -0.08120646f, -0.00995547f, -0.00101281f, -0.10908573f, -0.12723699f, 0.01036145f, 0.07578587f, -0.04847968f, -0.05435574f, 0.07650364f, 0.07471010f, -0.07950960f, -0.02903089f};
static const float L2_BIASES[2] = {-0.01394321f, -0.01403321f};

// Performs forward inference without dynamic memory allocation
static inline void actor_forward(const float input[4], float output[2]) {
    float buf_a[32];
    float buf_b[32];
    float* tmp; // Declared once at function level
    
    // Copy input into initial working buffer
    for (int i = 0; i < 4; i++) {
        buf_a[i] = input[i];
    }

    float* src = buf_a;
    float* dst = buf_b;

    // --- Layer 0 Execution ---
    for (int j = 0; j < 32; j++) {
        float sum = L0_BIASES[j];
        for (int k = 0; k < 4; k++) {
            sum += src[k] * L0_WEIGHTS[k * 32 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 1 Execution ---
    for (int j = 0; j < 32; j++) {
        float sum = L1_BIASES[j];
        for (int k = 0; k < 32; k++) {
            sum += src[k] * L1_WEIGHTS[k * 32 + j];
        }
        dst[j] = tanhf(sum);
    }
    tmp = src; src = dst; dst = tmp;

    // --- Layer 2 Execution ---
    for (int j = 0; j < 2; j++) {
        float sum = L2_BIASES[j];
        for (int k = 0; k < 32; k++) {
            sum += src[k] * L2_WEIGHTS[k * 2 + j];
        }
        dst[j] = sum;
    }

    // Copy final activation output to user buffer
    for (int i = 0; i < 2; i++) {
        output[i] = dst[i];
    }
}

